const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const newMexico = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'New Mexico'));
  const geom = newMexico.geometry();

  // Function to get MODIS LST for a given date range with quality masking
  function getLST(startDate, endDate) {
    const col = ee.ImageCollection('MODIS/061/MOD11A2')
      .filterDate(startDate, endDate)
      .filterBounds(geom);

    // Mask low quality pixels (QC_Day bits 0-1 = 0 for good quality)
    const maskQuality = function(img) {
      const qc = img.select('QC_Day');
      const qualityMask = qc.bitwiseAnd(3).eq(0); // bits 0-1 == 0
      return img.select('LST_Day_1km')
        .updateMask(qualityMask)
        .multiply(0.02) // Convert to Kelvin
        .subtract(273.15) // Convert to Celsius
        .copyProperties(img, ['system:time_start']);
    };

    return col.map(maskQuality);
  }

  // 2. Data Acquisition - 2016 period
  const lst2016 = getLST('2016-07-20', '2016-07-28');
  const lst2016Size = lst2016.size().getInfo();
  console.log(`2016 Images: ${lst2016Size}`);

  if (lst2016Size === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Data Acquisition - 2001-2010 average
  let yearlyImages = [];
  for (let year = 2001; year <= 2010; year++) {
    const col = getLST(`${year}-07-20`, `${year}-07-28`);
    const img = col.median();
    const count = col.size().getInfo();
    console.log(`${year}: ${count} images`);
    if (count > 0) {
      yearlyImages.push(img);
    }
  }

  if (yearlyImages.length === 0) {
    console.log('No images for 2001-2010');
    console.log('<answer>C1</answer>');
    return;
  }

  const multiYearComposite = ee.ImageCollection(yearlyImages).mean();
  const lst2016Image = lst2016.median();

  // 4. Calculate pixel counts to detect C2
  const count2016 = lst2016Image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const countAvg = multiYearComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log(`Valid pixels 2016: ${count2016}, Avg: ${countAvg}`);

  if (count2016 === 0 || countAvg === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate mean temperatures
  const mean2016 = lst2016Image.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geom,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const meanAvg = multiYearComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geom,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  console.log(`2016 Mean: ${mean2016?.toFixed(2)}°C`);
  console.log(`2001-2010 Mean: ${meanAvg?.toFixed(2)}°C`);

  // 6. Validate results
  if (mean2016 === null || meanAvg === null || 
      isNaN(mean2016) || isNaN(meanAvg) ||
      mean2016 < -100 || mean2016 > 100 || 
      meanAvg < -100 || meanAvg > 100) {
    console.log('<answer>C3</answer>');
    return;
  }

  // 7. Final comparison
  const isWarmer = mean2016 > meanAvg;
  console.log(`Warmer in 2016? ${isWarmer}`);
  console.log(isWarmer ? '<answer>A</answer>' : '<answer>B</answer>');
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
